(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,63398,e=>{e.v(JSON.parse('{"summary":{"name":"Richard Franks","title":"Principal / Distinguished-level Full-stack Engineer","heroOverline":"Principal Full Stack Engineer","documentTitle":"Richard Franks | Résumé","metadataTitle":"Richard Franks | Résumé","metadataDescription":"Résumé of Richard Franks, Principal Full Stack Engineer and AI-driven systems architect.","location":"Boston, MA / Derry, NH","avatarImage":"/personal/images/personal/me.jpeg","headshotImage":"/personal/images/personal/me-headshot.jpeg","resumeUrl":"/resume.pdf","contact":{"linkedin":"https://www.linkedin.com/in/richardfranksjr","email":"richardfranksjr@hotmail.com","github":["https://github.com/rfranks","https://github.com/rfrankspk"]},"gutter":["Principal / Distinguished-level full-stack engineer with 15 years of experience building production web applications, APIs, and domain-specific software across healthcare, fintech, and scientific-adjacent environments. Strong hands-on background in Python, Java, TypeScript, React, RESTful services, SQL/NoSQL-backed systems, and AI-enabled workflows.","Focused on building production systems where product complexity, domain complexity, and technical complexity all intersect, especially in healthcare and AI-assisted workflows.","Strong across the full stack: modern React and Next.js frontends, TypeScript and Python service layers, Java enterprise systems, and cloud-native delivery on Azure and AWS.","Operates comfortably at both architecture and execution depth, turning ambiguous requirements into shipped software while improving reliability, developer velocity, and long-term maintainability."]},"contactCTA":{"title":"Contact","body":"Open to principal-level full stack, AI platform, and product engineering opportunities where architecture and delivery both matter.","primaryLabel":"Email","secondaryLabel":"LinkedIn"},"portfolioApps":{"site":{"description":"Résumé of Richard Franks, Principal Full Stack Engineer and AI-driven systems architect."},"aiShenanigans":{"documentTitle":"AI Shenanigans","metadataTitle":"AI Shenanigans","metadataDescription":"Stylized AI experiments blending source photos, caricature renders, and optional motion passes.","appBarSubtitle":"Stylization, caricature, and optional motion","heroEyebrow":"Portfolio experiment"},"dna":{"documentTitle":"GeneBoard"},"bookworm":{"documentTitle":"Bookworm","interstitialAppName":"Bookworm","interstitialLogoAlt":"Bookworm logo"},"talentforge":{"documentTitle":"TalentForge"},"rickbert":{"documentTitle":"Rickbert Studio","metadataTitle":"Rickbert Studio","metadataDescription":"Structured comic strip generation studio for the RICKBERT series.","interstitialAppName":"Rickbert Studio","interstitialLogoAlt":"Rickbert Studio logo"}},"navigation":{"forkRibbon":{"label":"Make my own","href":"https://github.com/rfranks/portfolio/fork"},"drawerItems":[{"label":"Home","href":"/","icon":"home"},{"label":"GeneBoard","href":"/dna","icon":"science"},{"label":"Bookworm","href":"/bookworm","icon":"menuBook"},{"label":"TalentForge","href":"/talentforge","icon":"build"},{"label":"AI Shenanigans","href":"/ai-shenanigans","icon":"autoFixHigh"},{"label":"Rickbert Studio","href":"/rickbert","icon":"autoStories"},{"label":"Blackjack","href":"/blackjack","icon":"casino"},{"label":"Warbirds","href":"/warbirds","icon":"flight"}]},"competencies":{"categories":[{"title":"AI/LLM & RAG Systems","items":[{"label":"Retrieval-augmented generation","description":"Designing systems that ground model output in retrieved documents, records, and structured data."},{"label":"Large Language Models (LLM)","description":"Applying production LLM workflows for summarization, extraction, reasoning, and assistant experiences."},{"label":"LangChain","description":"Building TypeScript and Python orchestration pipelines for prompts, tools, retrieval, and evaluation."},{"label":"Clinical NLP with ICD-10/SNOMED/LOINC/RxNorm","description":"Mapping unstructured clinical language into medically relevant vocabularies and concepts."},{"label":"Deepgram","description":"Using streaming and batch speech-to-text APIs in multi-model transcription pipelines."},{"label":"AssemblyAI","description":"Integrating speech intelligence services for transcription, insights, and downstream extraction."},{"label":"AWS Transcribe","description":"Using managed AWS speech recognition for healthcare and general transcription workflows."},{"label":"AWS Comprehend Medical","description":"Extracting clinical entities, medications, conditions, and relationships from medical text."},{"label":"ElevenLabs","description":"Integrating voice synthesis and conversational audio capabilities into product workflows."}]},{"title":"Frontend","items":[{"label":"React","description":"Building complex interactive UIs with reusable component systems and state-driven rendering."},{"label":"Next.js","description":"Shipping production React applications with App Router, SSR, SSG, and API integrations."},{"label":"TypeScript","description":"Using static typing to improve correctness, maintainability, and shared contracts across stacks."},{"label":"React Native","description":"Delivering mobile application experiences with shared React patterns and native device access."},{"label":"Expo","description":"Accelerating React Native development, builds, and device feature integration with Expo tooling."},{"label":"Design systems","description":"Creating reusable UI primitives, tokens, and patterns for consistent product experiences."},{"label":"Monorepos (single-spa)","description":"Organizing large frontend codebases with shared packages and microfrontend-friendly architecture."},{"label":"Turborepo","description":"Managing monorepos with cached builds, shared packages, and coordinated multi-application development workflows."}]},{"title":"Backend","items":[{"label":"Python (Django, Flask, FastAPI)","description":"Building APIs, services, and data-processing backends across multiple Python frameworks."},{"label":"Java (Spring Boot/Hibernate)","description":"Designing enterprise service layers, domain models, and persistence-backed applications in Java."},{"label":"TypeScript APIs","description":"Implementing strongly typed backend services and internal APIs in the TypeScript ecosystem."},{"label":"NestJS","description":"Structuring scalable Node.js services with dependency injection, modules, and testable architecture."}]},{"title":"Cloud & DevOps","items":[{"label":"Azure Functions","description":"Deploying event-driven and HTTP-triggered serverless backends on Azure infrastructure."},{"label":"AWS","description":"Using managed AWS services for application hosting, AI integrations, and operational workflows."},{"label":"Amazon S3","description":"Using object storage for application assets, document pipelines, exports, and cloud-native data workflows."},{"label":"CosmosDB","description":"Designing globally distributed document persistence for cloud-native application workloads."},{"label":"Google Cloud Storage","description":"Managing object storage for files, data exchange, and cloud-hosted application workflows in Google Cloud environments."},{"label":"GitHub Actions CI/CD","description":"Automating builds, tests, releases, and deployment workflows directly in GitHub."},{"label":"Model deployment","description":"Deploying machine learning and AI models into production workflows with attention to reliability, versioning, and operational monitoring."},{"label":"Containerized deployments","description":"Packaging and shipping services consistently with container-based runtime environments."}]},{"title":"Data & Integration","items":[{"label":"REST APIs","description":"Designing and consuming HTTP APIs with stable contracts, authentication, and versioning."},{"label":"Event-driven microservices","description":"Building distributed systems that coordinate through asynchronous events and service boundaries."},{"label":"PostgreSQL","description":"Modeling relational data and tuning queries for reliable transactional application workloads."},{"label":"MongoDB","description":"Working with flexible document models for operational and product-facing application data."},{"label":"MySQL","description":"Supporting production relational data stores and integrations in enterprise environments."}]},{"title":"Leadership","items":[{"label":"Architecture board member","description":"Guiding platform direction, technical standards, and cross-team architectural decisions."},{"label":"Engineering mentor","description":"Coaching engineers through design reviews, implementation strategy, and technical growth."},{"label":"Cross-functional collaboration with product, UX, QA, and DevOps","description":"Translating business goals into shippable technical plans with strong delivery alignment."}]}],"skills":["React.js","TypeScript","Software Architecture","Large Language Models (LLM)","Retrieval-Augmented Generation (RAG)","LangChain","Python (Programming Language)","Team Leadership","Web Services","JavaScript","Agile","Spring Boot","Java","Spring","JSP","Python","Django","FastAPI","MySQL","REST","Backbone.js","jQuery","AJAX","HTML","CSS","Next.js","NestJS","React Native","Expo","J2EE","Swagger","Hibernate","JUnit","Ant","Subversion","Linux","Apache","Tomcat","XML","Servlets","Git","Google Analytics","IntelliJ IDEA","Eclipse","Maven","GitHub","GitHub Actions","UML","Windows","Mac OS X","PostgreSQL","MongoDB","Oracle SQL","Cascading Style Sheets (CSS)","Jenkins","JPA","SQL","Azure Functions","CosmosDB","Deepgram","AssemblyAI","AWS Transcribe","AWS Comprehend Medical","ElevenLabs","Leadership","Handlebars.js","Liferay","Portlets","Mercurial","TestNG","MVC"]},"coreCompetencies":["React.js","TypeScript","Software Architecture","Large Language Models (LLM)","Retrieval-Augmented Generation (RAG)","LangChain","Python (Programming Language)","Team Leadership","Web Services","JavaScript","Agile","Spring Boot","Java","Spring","JSP","Python","Django","FastAPI","MySQL","REST","Backbone.js","jQuery","AJAX","HTML","CSS","Next.js","NestJS","React Native","Expo","J2EE","Swagger","Hibernate","JUnit","Ant","Subversion","Linux","Apache","Tomcat","XML","Servlets","Git","Google Analytics","IntelliJ IDEA","Eclipse","Maven","GitHub","GitHub Actions","UML","Windows","Mac OS X","PostgreSQL","MongoDB","Oracle SQL","Cascading Style Sheets (CSS)","Jenkins","JPA","SQL","Azure Functions","CosmosDB","Deepgram","AssemblyAI","AWS Transcribe","AWS Comprehend Medical","ElevenLabs","Leadership","Handlebars.js","Liferay","Portlets","Mercurial","TestNG","MVC"],"hobbies":{"title":"Hobbies","heroImageUrl":"/personal/images/hobbies-hero.png","heroVideoUrl":null,"items":["Sea-dooing","Pinball","Retro arcades and gaming in general","Lego Star Wars everything","AI Shennanigans","Boston sports teams"],"introText":"Things I keep coming back to outside of work when I want speed, flow, competition, and a little nostalgia."},"aiShenanigans":{"title":"AI Shenanigans","description":"Little experiments in stylization, caricature, and motion where a grounded source image gets pushed into something stranger, warmer, and more playful.","items":[{"slug":"momma-helen","title":"Momma Helen\'s Deep Frying","orientation":"portrait","realisticImage":"/personal/images/ai-shenanigans/momma-helen/realistic.jpeg","realisticSource":"Photo (Richard Franks Jr)","realisticCaption":"The grounded portrait that anchors the whole transformation before the caricature and motion take over.  That\'s not chicken!   It\'s the rump of a frog!","stylizedRendering":"/personal/images/ai-shenanigans/momma-helen/stylistic.png","stylizedSource":"ChatGPT DALL-E image generation","stylizedCaption":"The likeness gets pushed into a warmer, more playful cartoon rendering with the expression exaggerated for comic effect.","movieRendering":"/personal/images/ai-shenanigans/momma-helen/movie.mp4","movieSource":"Sora video generation","movieCaption":"The caricature turns into a short motion beat, leaning into Momma Helen\'s delighted reaction to her first taste of deep-fried frog legs.  The frogs are not impressed.","blurb":"Momma Helen, reimagined as a full cartoon caricature, tries deep-fried frog legs for the first time and immediately loves them. The whole piece leans into that exact moment of delighted surprise, where one crispy bite turns into a kitchen-table legend and Momma Helen decides this absolutely belongs in the regular rotation."},{"slug":"budweiser-pacman","title":"Budweiser Pac-Man","orientation":"portrait","realisticImage":"/personal/images/ai-shenanigans/budweiser-pacman/realistic.jpeg","realisticSource":"Photo (Richard Franks Jr)","realisticCaption":"A real-world Pac-Man-meets-Budweiser scene that already feels a little surreal before any AI motion gets involved.","movieRendering":"/personal/images/ai-shenanigans/budweiser-pacman/movie.mp4","movieSource":"Sora video generation","movieCaption":"The still gets pushed straight into motion, letting the arcade-meets-beer-sign energy do the work without an intermediate stylized frame.","blurb":"A Budweiser-and-Pac-Man visual mashup that skips the caricature pass and goes straight from the photographed source into motion. This one plays more like a retro ad fragment: bright, weird, nostalgic, and just a little overcaffeinated."},{"slug":"ricky-franks-jr-2b","title":"Ricky Franks Jr - Topps Trader 2B","orientation":"portrait","realisticImage":"/personal/images/ai-shenanigans/ricky-franks-jr-2b/realistic.jpeg","realisticSource":"Unknown","realisticCaption":"The original image that kicks off the baseball-card fantasy before the stylized trader pass turns it into something collectible.  Start with my headshot!","stylizedRendering":"/personal/images/ai-shenanigans/ricky-franks-jr-2b/stylistic.png","stylizedSource":"Richard\'s Topps Trader GPT","stylizedSourceHref":"https://chatgpt.com/g/g-69aa197ad56c8191bfd45be339970b4b-topps-trader","stylizedCaption":"The image gets reframed like a dream Topps pull, leaning into the fantasy of Ricky Franks Jr. landing on a card as the Red Sox second baseman.","movieRendering":"/personal/images/ai-shenanigans/ricky-franks-jr-2b/movie.mp4","movieSource":"Sora video generation","movieCaption":"The card fantasy comes alive in motion, pushing the baseball-daydream energy a step past the still frame.","blurb":"Ricky Franks dreams of having his own Topps card and lining up at second base for the Red Sox. This shenanigan turns that baseball-kid fantasy into a trading-card moment, then lets it come to life in motion like a highlight reel from an alternate timeline."},{"slug":"millie-and-graham","title":"Best Day Ever!","orientation":"portrait","realisticImage":"/personal/images/ai-shenanigans/millie-and-graham/realistic.jpg","realisticSource":"Photo (Richard Franks Jr)","realisticCaption":"The real moment: brave little Millie meeting the biggest friend she could imagine in Graham, the giant black horse.","stylizedRendering":"/personal/images/ai-shenanigans/millie-and-graham/stylized.png","stylizedSource":"ChatGPT DALL-E image generation","stylizedCaption":"The meeting gets softened into a storybook-style rendering, keeping Millie\'s courage and Graham\'s calm size at the center.","movieRendering":"/personal/images/ai-shenanigans/millie-and-graham/movie.mp4","movieSource":"Sora video generation","movieCaption":"The still moment turns into a small cinematic beat, leaning into the feeling that this was absolutely Millie\'s best day ever.","blurb":"Brave little Millie meets her biggest best friend in Graham, a giant black horse who somehow manages to feel both enormous and gentle at the same time. The whole shenanigan leans into that instant connection, where Millie looks like she knows she just stumbled into the best day ever."},{"slug":"universal-monster","title":"Universal Monster!","orientation":"landscape","realisticImage":"/personal/images/ai-shenanigans/universal-monster/realistic.jpeg","realisticSource":"Photo (Richard Franks Jr)","realisticCaption":"A selfie becomes the launch point for a monster-movie riff before the whole thing starts moving like a studio trailer fragment.","movieRendering":"/personal/images/ai-shenanigans/universal-monster/movie.mp4","movieSource":"Sora video generation","movieCaption":"Universal energy comes alive in motion as the monsters close in and the whole scene tips into playful terror.","blurb":"Universal comes alive and the monsters terrorize. This shenanigan takes a simple Richard Franks Jr. selfie and pushes it straight into a motion-heavy creature-feature beat, like a personal snapshot accidentally wandered onto a classic monster backlot."},{"slug":"luck-o-the-irish","title":"Luck o\' the Irish!","orientation":"portrait","realisticImage":"/personal/images/ai-shenanigans/luck-o-the-irish/realistic.jpeg","realisticSource":"Photo (Richard Franks Jr)","realisticCaption":"Start with the headshot, then lean hard into the St. Patty\'s Day fantasy version of me as a leprechaun.","stylizedRendering":"/personal/images/ai-shenanigans/luck-o-the-irish/stylistic.png","stylizedSource":"ChatGPT DALL-E image generation","stylizedCaption":"The portrait gets pushed into a shamrock-soaked caricature, turning me into the kind of leprechaun who should probably not be trusted with your gold.","movieRendering":"/personal/images/ai-shenanigans/luck-o-the-irish/movie.mp4","movieSource":"Sora video generation","movieCaption":"The whole bit tips into motion like a festive little fever dream, proving that if I have the luck of the Irish, it is definitely not always working.","blurb":"Me as a St. Patty\'s Day leprechaun, because apparently I am a lot more Irish than expected according to 23andMe. The joke, of course, is that if I really do have the luck of the Irish, it sure does not show up on command."},{"slug":"rick-pinball-in-yarn","title":"Pinball Yarnster!","orientation":"portrait","realisticImage":"/personal/images/ai-shenanigans/rick-pinball-in-yarn/realistic.jpeg","realisticSource":"Photo (Anne Barbarick)","realisticCaption":"A real portrait drops Rick into the machine before the whole thing gets pushed into a playful pinball-fantasy world.","stylizedRendering":"/personal/images/ai-shenanigans/rick-pinball-in-yarn/stylistic.png","stylizedSource":"ChatGPT DALL-E image generation","stylizedCaption":"The portrait turns into a yarny, pinball-infused caricature with just enough chaos to feel like multiball is about to start.","movieRendering":"/personal/images/ai-shenanigans/rick-pinball-in-yarn/movie.mp4","movieSource":"Sora video generation","movieCaption":"The whole scene springs to life in motion, like the machine woke up and decided Rick gets to have his pinball moment after all.","blurb":"Rick gets his pinball on. This shenanigan takes a portrait and pushes it into a bizarre pinball-meets-yarn fever dream, where the lights are hot, the action is chaotic, and the whole thing feels like a bonus round built specifically for Rick."},{"slug":"the-rock","type":"book-to-limited-series","title":"The Rock By Frank Richards","orientation":"landscape","intentToCopyright":true,"rightsNotice":"Intent to Copyright","bookCoverImage":"/personal/images/ai-shenanigans/the-rock/book-cover.png","bookSource":"Book cover / manuscript concept","bookCaption":"The cover frames The Rock as a desert science-thriller built around Uluru, secrecy, and the sense that something engineered and ancient is buried inside the stone.","manuscriptPdf":"/personal/images/ai-shenanigans/the-rock/manuscript.pdf","manuscriptSource":"Manuscript draft","manuscriptCaption":"The manuscript opens with Mara Vance\'s survey team at Uluru uncovering an impossible void: smooth planes, machined seams, metallic dust, a failed probe contact, and the first hint that the rock may actually be a vessel.","episodesPdf":"/personal/images/ai-shenanigans/the-rock/episodes.pdf","episodesSource":"Episode plan / limited series notes","episodesCaption":"The episodes draft maps the story into a prestige limited-series arc: first the team finds the door, then they recognize the geometry as a vessel, and finally the mystery widens into a planetary-scale emergency.","episodeMedia":[{"title":"The Dust Chamber","episodeNumber":1,"src":"/personal/images/ai-shenanigans/the-rock/episode1.mp4","source":"Sora video generation","caption":"Episode 1 stages the Uluru discovery as a slow-burn field thriller: predawn convoy, anomaly scans, drill validation, first contact with the hidden surface, then blackout, tremor, and storm as Mara realizes they did not find a chamber, but a door."},{"title":"The Silent Geometry","episodeNumber":2,"src":"/personal/images/ai-shenanigans/the-rock/episode2.mp4","source":"Sora video generation","caption":"Episode 2 picks up in the aftermath of contact: corrupted readings, Uncle Jarra\'s warning, geometric grooves on the outer skin of Uluru, and tomography that reveals decks, seams, and the first unmistakable evidence that the monolith is hiding a vessel."},{"title":"A Failing World","episodeNumber":3,"src":"/personal/images/ai-shenanigans/the-rock/episode3.mp4","source":"Sora video generation","caption":"Episode 3 widens the scope from site mystery to global crisis: drifting compasses, failing systems, emergency briefings, and opening internal corridors that suggest the buried craft is waking because the world itself is entering failure."}],"blurb":"The Rock starts as a tightly grounded survey-thriller at Uluru and opens into a prestige science-fiction mystery about an engineered structure hidden inside the monolith. The manuscript\'s first movement follows Mara Vance from anomaly scan to first contact; the episodes draft then scales that discovery into a serialized arc about a buried vessel, a waking storm, and a world sliding toward systems failure."},{"slug":"creepy-cryptids","type":"work-to-series-adaptation","title":"P.T. Barnum\'s Creepy Cryptids","orientation":"portrait","intentToCopyright":true,"rightsNotice":"Intent to Copyright","workParts":[{"src":"/personal/images/ai-shenanigans/creepy-cryptids/creepy-cryptids-part-1.pdf","title":"Work Part 1","source":"Richard Franks (writing as Frank Richards) with the help of ChatGPT","caption":"The opening section establishes the Victorian broadside premise, framing Creepy Cryptids as a forgotten Barnum-era exhibition where scholarship and sensationalism are fused into one traveling cabinet of horrors."},{"src":"/personal/images/ai-shenanigans/creepy-cryptids/creepy-cryptids-part-2.pdf","title":"Work Part 2","source":"Richard Franks (writing as Frank Richards) with the help of ChatGPT","caption":"Part two deepens the faux encyclopedia rhythm, treating each creature like both a documented regional terror and a ticket-selling sideshow attraction in equal measure."},{"src":"/personal/images/ai-shenanigans/creepy-cryptids/creepy-cryptids-part-3.pdf","title":"Work Part 3","source":"Richard Franks (writing as Frank Richards) with the help of ChatGPT","caption":"The middle-late spreads widen the geography and mythology, reinforcing the project\'s global cryptid sweep while keeping the vintage horror-art-book tone intact."},{"src":"/personal/images/ai-shenanigans/creepy-cryptids/creepy-cryptids-part-4.pdf","title":"Work Part 4","source":"Richard Franks (writing as Frank Richards) with the help of ChatGPT","caption":"The closing section completes the cabinet-of-nightmares effect, leaving the work feeling like a fully realized Barnum-style archive of monstrosities, warnings, and theatrical dread."}],"seriesParts":[{"src":"/personal/images/ai-shenanigans/creepy-cryptids/creepy-cryptids-part-1.mp4","title":"Series Part 1","source":"Sora video generation","caption":"Part one of the series adaptation leans into the anthology-show opening energy, where each creature feels poised to step out of folklore and into staged Victorian spectacle."},{"src":"/personal/images/ai-shenanigans/creepy-cryptids/creepy-cryptids-part-2.mp4","title":"Series Part 2","source":"Sora video generation","caption":"Part two carries the anthology mood forward, pushing the concept toward a serialized cabinet of regional terrors, traveling menace, and showman-horror pageantry."}],"blurb":"P.T. Barnum\'s Creepy Cryptids is a vintage horror art-book concept that reimagines obscure folkloric creatures as the headline attractions of a lost nineteenth-century traveling sideshow. Each creature is treated as both scholarship and spectacle: one page reads like an antique encyclopedia entry full of lore, maps, warnings, and taxonomy, while the facing page explodes into a sensational Barnum-style broadside. The result is a cabinet of international nightmares where eerie research meets carnival showmanship, and every spread asks what dreadful thing Barnum has dragged back this time."}]},"experience":[{"company":"Carebrain","position":"Distinguished Engineer","location":"Remote","start":"September 2025","end":"March 2026","image":"/personal/images/employers/carebrain.jpeg","details":["Onboarded rapidly from a Java/Python background into a full TypeScript/Next.js/NestJS monorepo.","Built a LangChain-based pipeline with intelligent model selection and answer evaluation, improving answer quality and model choice instead of relying on fixed one-shot prompting to a single vendor, preventing vendor lock-in and increasing uptime.","Implemented an in-person scribe workflow using Deepgram, AssemblyAI, ElevenLabs, AWS Transcribe Medical, and AWS Comprehend Medical, with extraction of topics, keywords, insights, and tasks at 95%+ accuracy.","Implemented HIPAA audit logging for 100% of PHI transfer paths: monorepo services, internal APIs, third-party APIs, and database-level transactions.","Built a patient list browser allowing a user to browse relevant EHR medical data and view clinical indicators, either pre-computed or computed on-the-fly from static analysis or LLM queries.","Improved Telehealth transcription workflows to 95%+ accuracy.","Implemented a Slack-like clinician-to-clinician group chat client built on top of GetStream.io."],"achievements":["Achieved 95%+ transcription/data extraction accuracy across multiple extraction modes (topics, keywords, insights).","Shipped approximately 5x more features than peers on comparable scope."]},{"company":"Commure","position":"Senior Software Architect / Principal Software Engineer","location":"Remote","start":"June 2022","end":"September 2025","image":"/personal/images/employers/commure.jpeg","details":["Architected and built an AI copilot using RAG and multiple LLMs over clinical EHR data, including summary generation and direct question answering.","Built a Python service calling CosmosDB and MongoDB stores, creating embeddings, querying documents, utilizing LangChain to call multiple LLM vendors, and performing answer analysis, evaluation, and validation.","Extended the AI copilot system to analyze progress notes, extract complications and risk factors, and support downstream recommendations tied to clinical coding systems like ICD-10 and CPT codes.","Brought applied AI capabilities into production workflows in a highly specialized domain, working across software, data, and end-user needs."],"achievements":["Delivered multiple AI-powered clinical tools now in production use.","Accelerated delivery pipelines via GitHub Actions automation."]},{"company":"PatientKeeper","position":"Principal Software Engineer / Architect","location":"Waltham, MA","start":"December 2013","end":"September 2021","details":["Rebuilt the portal application framework to support loosely coupled product screens across multiple suites using a Backbone.js/Handlebars MVC architecture with a RESTful Java Spring backend.","Helped reimagine the EHR with a dashboard framework supporting 200+ robust gadget implementations.","Created reusable custom components used across the engineering organization, including Patient List and Patient Assignment workflows.","Led design sessions, code reviews, created diagrams and documentation, mentored engineers, and integrated automated tests into CI/CD pipelines.","Served as an active member of the Architecture Board.","Led teams of up to 3-5 members."],"achievements":["Recognized with STAR Award (2020).","Employee of the Quarter nomination (2018)."],"image":"/personal/images/employers/patientkeeper.png"},{"company":"DressageMarket.com, LLC","position":"Chief Engineer / Entrepreneur","location":"Remote","start":"August 2009","end":"March 2021","image":"/personal/images/employers/dressagemarket.jpg","details":["Cofounded and served as sole engineer for a web-based classified marketplace, owning product architecture, implementation, and ongoing evolution end to end.","Worked closely with other cofounders to shape the product roadmap and help materialize the business vision.","Built the platform using Python and Django."]},{"company":"CashStar","position":"Engineer","location":"Portland, ME","start":"June 2009","end":"October 2010","details":["Led engineering on a Java REST service layer connecting a customer-facing application to external gift-card processors.","Built and certified integrations with major credit card processors and supported launches across 36 national and regional brands.","Maintained 99.88% uptime while supporting the service in production and strengthening automated testing and CI workflows."],"image":"/personal/images/employers/cashstar.png"},{"company":"REZ-1","position":"Software Engineering Consultant","location":"Wellesley, MA","start":"October 2010","end":"June 2012","details":["Contributed across the full stack on a large-scale enterprise rewrite for freight marketplace software, spanning UI, middle-tier services, backend entities, testing, deployment, and maintenance.","Worked with Vaadin, Liferay, Tomcat, Spring, Hibernate, JPA, JAX-WS, and jUnit, including contribution to an annotation-driven framework for faster development."]},{"company":"IDEXX","position":"Consultant","details":["Consultant on veterinary practice management platform."]},{"company":"Fetch Enterprises","position":"Full-stack Developer","details":["Full-stack developer focused on Java-based web application development."]}],"projects":[{"name":"Rickbert Studio","description":"Client-side comic strip production studio with parser, validation preflight, react-konva rendering, and PNG export.","href":"/rickbert","type":"personal","interestsMeWhy":"This project separates domain parsing, checklist validation, and vector rendering so the comic engine can be reused as a shared module across a broader product portfolio.","watermark":{"kind":"image","containerClassName":"pointer-events-none absolute bottom-4 right-4 opacity-[0.1] transition-all duration-500 group-hover:translate-y-[-2px] group-hover:opacity-[0.18]","src":"/images/projects/rickbert-studio.png","alt":"Rickbert Studio watermark","width":300,"height":200,"imageClassName":"h-auto w-56 object-contain"}},{"name":"Warbirds","description":"Dogfight through the skies in this arcade shooter.","href":"/warbirds","type":"personal","interestsMeWhy":"Building an aerial combat game pushed my understanding of canvas rendering and simple AI. It\'s a fun showcase of real-time physics entirely in the browser.","watermark":{"kind":"image","containerClassName":"pointer-events-none absolute bottom-5 right-4 opacity-[0.12] transition-all duration-500 group-hover:translate-y-[-2px] group-hover:opacity-[0.2]","src":"/assets/titles/warbirds_title.png","alt":"Warbirds watermark","width":240,"height":88,"imageClassName":"h-auto w-48 object-contain"}},{"name":"Blackjack","description":"Classic twenty-one card game against the dealer.","href":"/blackjack","type":"personal","interestsMeWhy":"The project highlights state management and probability in a familiar game. It\'s a clean example of how to model rules and player interaction.  It also illustrates how business logic in Go can be run both on the server and compiled to WebAssembly for client-side play.  This business logic is shared via the web, the raw terminal, and via the VSCode Go debugger versions.","watermark":{"kind":"cardsFan","containerClassName":"pointer-events-none absolute bottom-3 right-3 h-36 w-40 opacity-[0.16] transition-all duration-500 group-hover:scale-[1.03] group-hover:opacity-[0.24]","cards":[{"src":"/assets/cards/PNG/Cards (medium)/card_back.png","alt":"Playing card back","width":128,"height":179,"className":"absolute left-0 top-5 h-28 w-auto rounded-lg object-contain drop-shadow-lg"},{"src":"/assets/cards/PNG/Cards (medium)/card_spades_J.png","alt":"Jack of spades","width":128,"height":179,"className":"absolute left-7 top-2 h-28 w-auto rounded-lg object-contain drop-shadow-lg"},{"src":"/assets/cards/PNG/Cards (medium)/card_spades_A.png","alt":"Ace of spades","width":128,"height":179,"className":"absolute left-14 top-0 h-28 w-auto rounded-lg object-contain drop-shadow-lg"}]},"diagrams":[{"title":"Blackjack Component Diagram","type":"flowchart","height":420,"diagram":"flowchart LR\\n  User[\\"Player\\"] --> ReactUI[\\"Next.js Blackjack Page\\"]\\n  ReactUI --> Audio[\\"Audio Hooks\\\\nuseAudio / useBGM / useAmbience\\"]\\n  ReactUI --> Bus[\\"window.postMessage Bus\\"]\\n  Bus --> WebUI[\\"Go WASM WebUI\\\\nui/web/web.go\\"]\\n  WebUI --> Engine[\\"Blackjack Engine\\\\ndealer / game / player / sidebets\\"]\\n  Engine --> StateBuilder[\\"Render State Builder\\\\nui/web/messages.go\\"]\\n  StateBuilder --> WebUI\\n  WebUI --> Bus\\n  Bus --> ReactUI\\n  ReactUI --> DOM[\\"Rendered Cards / Controls / Status\\"]\\n  ReactUI --> Audio"},{"title":"Blackjack Sequence Diagram","type":"sequenceDiagram","height":460,"diagram":"sequenceDiagram\\n  actor User\\n  participant React as React UI\\n  participant Bus as postMessage Bus\\n  participant WebUI as Go WASM WebUI\\n  participant Engine as Blackjack Engine\\n\\n  User->>React: Click Go! Blackjack!\\n  React->>Bus: blackjack/start\\n  Bus->>WebUI: start message\\n  WebUI->>Engine: deal opening round\\n  Engine-->>WebUI: updated game state\\n  WebUI->>Bus: blackjack/state\\n  Bus->>React: render state\\n  React-->>User: show dealer, hands, controls\\n\\n  User->>React: Hit / Stand / Double / Split\\n  React->>Bus: blackjack/action\\n  Bus->>WebUI: action message\\n  WebUI->>Engine: advance round\\n  Engine-->>WebUI: settled or in-progress state\\n  WebUI->>Bus: blackjack/state\\n  Bus->>React: next render state\\n\\n  User->>React: Toggle game mode\\n  React->>Bus: blackjack/toggle-game-mode\\n  Bus->>WebUI: mode toggle message\\n  WebUI->>Engine: rebuild mode-specific round state\\n  WebUI->>Bus: blackjack/state"},{"title":"Blackjack Block Diagram","type":"flowchart","height":460,"diagram":"flowchart TB\\n  subgraph Presentation[\\"Presentation Layer\\"]\\n    ReactPage[\\"Blackjack Page\\"]\\n    Controls[\\"Buttons / Chips / Hand Views\\"]\\n    Media[\\"Audio + Animations\\"]\\n  end\\n\\n  subgraph Messaging[\\"Event Bus Boundary\\"]\\n    StartMsg[\\"blackjack/start\\"]\\n    ActionMsg[\\"blackjack/action\\"]\\n    ToggleMsg[\\"blackjack/toggle-game-mode\\"]\\n    StateMsg[\\"blackjack/state\\"]\\n  end\\n\\n  subgraph WasmAdapter[\\"WASM Adapter Layer\\"]\\n    WebAdapter[\\"WebUI Message Bridge\\"]\\n    RenderState[\\"Render DTO Assembly\\"]\\n  end\\n\\n  subgraph Domain[\\"Game Domain Layer\\"]\\n    Dealer[\\"Dealer / Shoe / Payouts\\"]\\n    GameMode[\\"Mode Rules\\"]\\n    PlayerState[\\"Hands / Wagers / Outcomes\\"]\\n  end\\n\\n  ReactPage --> Controls\\n  ReactPage --> Media\\n  Controls --> StartMsg\\n  Controls --> ActionMsg\\n  Controls --> ToggleMsg\\n  StartMsg --> WebAdapter\\n  ActionMsg --> WebAdapter\\n  ToggleMsg --> WebAdapter\\n  WebAdapter --> Dealer\\n  WebAdapter --> GameMode\\n  WebAdapter --> PlayerState\\n  Dealer --> RenderState\\n  GameMode --> RenderState\\n  PlayerState --> RenderState\\n  RenderState --> StateMsg\\n  StateMsg --> ReactPage"},{"title":"Blackjack Render State Model","type":"classDiagram","height":520,"diagram":"classDiagram\\n  class BlackjackRenderState {\\n    +bool hasRendered\\n    +bool askingToDeal\\n    +bool askingForInsurance\\n    +int house\\n    +int count\\n    +string gameMode\\n    +string gameModeLabel\\n    +string statusText\\n    +string hintText\\n  }\\n\\n  class BlackjackControlsView {\\n    +bool deal\\n    +bool hit\\n    +bool stand\\n    +bool double\\n    +bool split\\n    +bool insure\\n    +bool decline\\n  }\\n\\n  class BlackjackDealerView {\\n    +string totalLabel\\n    +BlackjackCardView[] cards\\n  }\\n\\n  class BlackjackPlayerView {\\n    +int stack\\n    +int winnings\\n    +string winningsDisplay\\n    +string winningsTone\\n    +BlackjackPlayerHandView[] hands\\n  }\\n\\n  class BlackjackPlayerHandView {\\n    +int index\\n    +bool active\\n    +int wager\\n    +bool busted\\n    +string totalLabel\\n    +string note\\n    +string outcomeLabel\\n    +BlackjackCardView[] cards\\n  }\\n\\n  class BlackjackCardView {\\n    +bool masked\\n    +string suit\\n    +string value\\n  }\\n\\n  class BlackjackResultView {\\n    +string badge\\n    +string tone\\n    +string summary\\n    +string[] detailLines\\n  }\\n\\n  BlackjackRenderState --> BlackjackControlsView : controls\\n  BlackjackRenderState --> BlackjackDealerView : dealer\\n  BlackjackRenderState --> BlackjackPlayerView : player\\n  BlackjackRenderState --> BlackjackResultView : result\\n  BlackjackDealerView --> BlackjackCardView : cards\\n  BlackjackPlayerView --> BlackjackPlayerHandView : hands\\n  BlackjackPlayerHandView --> BlackjackCardView : cards"},{"title":"Blackjack Round State Diagram","type":"stateDiagram-v2","height":520,"diagram":"stateDiagram-v2\\n  [*] --> WaitingToDeal\\n  WaitingToDeal --> DealingOpeningCards : Deal / Start\\n  DealingOpeningCards --> OfferInsurance : Dealer ace showing\\n  DealingOpeningCards --> CheckNaturals : Otherwise\\n  OfferInsurance --> CheckNaturals : Insure / Decline\\n  CheckNaturals --> RoundSettled : Dealer blackjack or player blackjack resolution\\n  CheckNaturals --> PlayerTurn : No naturals\\n\\n  state PlayerTurn {\\n    [*] --> EvaluateHand\\n    EvaluateHand --> EvaluateHand : Hit\\n    EvaluateHand --> AdvanceSplitHand : Stand\\n    EvaluateHand --> AdvanceSplitHand : Double\\n    EvaluateHand --> SplitHand : Split\\n    SplitHand --> EvaluateHand\\n    EvaluateHand --> AdvanceSplitHand : Bust\\n    AdvanceSplitHand --> EvaluateHand : Next active split hand\\n    AdvanceSplitHand --> [*] : No active hands remain\\n  }\\n\\n  PlayerTurn --> DealerTurn : All player hands locked\\n  DealerTurn --> DealerTurn : Draw to rule threshold\\n  DealerTurn --> SettleHands : Stand / Bust threshold reached\\n  SettleHands --> RoundSettled\\n  RoundSettled --> WaitingToDeal : Deal Again"}]},{"name":"Blasteroids","description":"Classic Asteroids arcade game with a space shooter twist.  Built entirely with HTML, CSS, and JavaScript.","href":"/blasteroids","type":"personal","interestsMeWhy":"Recreating a classic arcade title using only web standards was a technical challenge. It demonstrates how far raw HTML, CSS, and JavaScript can go.","accolades":[{"name":"Arctic Code Vault Contributor","source":"GitHub Archive Program","sourceUrl":"https://archiveprogram.github.com/arctic-vault/","description":"rfranks contributed code to 1 repository in the 2020 GitHub Archive Program.  The repository for blasteroids was archived to the Arctic Code Vault!","comment":"Honored to have my code preserved in the Arctic Code Vault for future generations!  Just one issue, how do I commit to GitHub in the Arctic? We would like to release more code, but the wifi is terrible.","launchUrl":"/blasteroids","githubUrl":"https://github.com/rfranks/blasteroids","imageSrcUrl":"/github-arctic-code-vault-contributor.png","date":"February 2, 2020"}],"watermark":{"kind":"image","containerClassName":"pointer-events-none absolute bottom-4 right-4 opacity-[0.1] transition-all duration-500 group-hover:translate-y-[-2px] group-hover:opacity-[0.18]","src":"/images/projects/blasteroids.jpeg","alt":"Blasteroids watermark","width":320,"height":220,"imageClassName":"h-auto w-56 rounded-2xl object-contain"}},{"name":"GeneBoard","description":"Interactive tools for exploring and visualizing DNA sequences.","href":"/dna","type":"personal","interestsMeWhy":"Combining biology and interactive graphics makes genomics approachable. It allowed me to explore data visualization beyond typical web apps.","watermark":{"kind":"image","containerClassName":"pointer-events-none absolute bottom-8 right-4 opacity-[0.1] transition-all duration-500 group-hover:translate-y-[-2px] group-hover:opacity-[0.18]","src":"/dna/images/geneboard_banner.png","alt":"GeneBoard watermark","width":240,"height":72,"imageClassName":"h-auto w-52 object-contain"}},{"name":"Bookworm","description":"AI powered PDF interactive AI chat bot.","href":"/bookworm","type":"personal","interestsMeWhy":"Integrating LLMs with PDF parsing shows how AI can unlock static documents. It was exciting to craft a conversational interface over complex texts.","watermark":{"kind":"image","containerClassName":"pointer-events-none absolute bottom-5 right-5 opacity-[0.08] transition-opacity duration-500 group-hover:opacity-[0.14]","src":"/logo192.png","alt":"Bookworm watermark","width":192,"height":194,"imageClassName":"h-28 w-28 rounded-3xl object-contain"}},{"name":"TalentForge","description":"AI-assisted career and offer strategy workspace for tracking applications, comparing offers, and managing negotiation playbooks.","href":"/talentforge","type":"personal","interestsMeWhy":"It brings together structured workflow design, AI assistance, and practical decision support in a way that feels like a real product rather than just a demo.","watermark":null},{"name":"AI Shenanigans","description":"Stylization and caricature experiments that transform grounded source images into playful rendered scenes, with optional motion passes layered on top.","href":"/ai-shenanigans","type":"personal","interestsMeWhy":"This one is fun because it treats image generation less like a one-shot prompt and more like a staged reveal: source material, stylized interpretation, then motion. It turns AI output into a little storytelling sequence instead of a single artifact.","watermark":{"kind":"image","containerClassName":"pointer-events-none absolute bottom-5 right-5 opacity-[0.1] transition-all duration-500 group-hover:translate-y-[-2px] group-hover:opacity-[0.18]","src":"/personal/images/ai-shenanigans/momma-helen/stylistic.png","alt":"AI Shenanigans watermark","width":280,"height":280,"imageClassName":"h-32 w-32 rounded-[28px] object-cover"}},{"name":"Patient List Project","description":"Backbone.js-based configurable patient visit list for physicians.  Spring backend with REST APIs, complex filtering, sorting, and pagination.","href":"/patientlist","type":"work","interestsMeWhy":"Transforming dense clinical data into a customizable dashboard was both challenging and rewarding. It illustrates the power of modern JavaScript in healthcare.","watermark":{"kind":"image","containerClassName":"pointer-events-none absolute bottom-5 right-5 opacity-[0.12] transition-all duration-500 group-hover:translate-y-[-2px] group-hover:opacity-[0.2]","src":"/personal/images/employers/patientkeeper.png","alt":"PatientKeeper watermark","width":280,"height":140,"imageClassName":"h-auto w-56 object-contain"}},{"name":"Patient Assignment List Project","description":"Backbone.js-based manageable patient assignment list for physicians.  Complex drag-and-drop UI, time-based and filter-based population criteria.","href":"/assignmentlist","type":"work","interestsMeWhy":"Designing drag-and-drop assignment logic for clinicians pushed the limits of the UI. The project blends real-time updates with intuitive workflow design.","watermark":{"kind":"image","containerClassName":"pointer-events-none absolute bottom-5 right-5 opacity-[0.12] transition-all duration-500 group-hover:translate-y-[-2px] group-hover:opacity-[0.2]","src":"/personal/images/employers/patientkeeper.png","alt":"PatientKeeper watermark","width":280,"height":140,"imageClassName":"h-auto w-56 object-contain"}},{"name":"AI-Driven Clinical Copilot","description":"Next.js/React frontend with Python/Azure Functions backend.  Integrates LLMs and retrieval-augmented generation (RAG) to summarize EHR data and answer questions with citations.","href":"/aisummary","type":"work","interestsMeWhy":"This project brings generative AI directly into physician workflows. It showcases how RAG can surface meaningful insights from enormous EHR datasets.","watermark":{"kind":"image","containerClassName":"pointer-events-none absolute bottom-5 right-5 opacity-[0.12] transition-all duration-500 group-hover:translate-y-[-2px] group-hover:opacity-[0.2]","src":"/personal/images/employers/commure.jpeg","alt":"Commure watermark","width":240,"height":240,"imageClassName":"h-28 w-28 rounded-3xl object-contain"}},{"name":"AI Patient List Podcasts","description":"Podcasts discussing the last 12 hours of clinically significant events for a list of patients.","href":"/patientlistpodcasts","type":"work","interestsMeWhy":"Turning clinical events into podcasts explores a novel medium for physician updates. It combines summarization, text-to-speech, and healthcare data.","watermark":{"kind":"image","containerClassName":"pointer-events-none absolute bottom-5 right-5 opacity-[0.12] transition-all duration-500 group-hover:translate-y-[-2px] group-hover:opacity-[0.2]","src":"/personal/images/employers/commure.jpeg","alt":"Commure watermark","width":240,"height":240,"imageClassName":"h-28 w-28 rounded-3xl object-contain"}},{"name":"Petly","description":"Pet owner portal mixing a social feed with full veterinary EHR access including vaccinations, x-rays, visits, and invoices.","href":"/petly","type":"work","interestsMeWhy":"At IDEXX we reshaped boxy Liferay portals into a playful notebook of sticky notes, lists, and photos—no square portlets in sight.","watermark":null}],"recognition":{"snippets":["Hailed as an exceptional architect blending technical mastery with lightning-fast execution.","Praised by colleagues as \\"the most brilliant engineer I’ve worked with… the closest to a 10x developer\\" and a \\"true team player and mentor.\\"","Trusted go-to for solving critical, high-stakes production issues with speed and quality.","Recognized repeatedly for leadership, mentorship, and engineering excellence."],"recommendations":[{"name":"Jay Patel","title":"Senior Software Engineer","date":"September 9, 2025","relationship":"Richard was senior to Jay but didn\'t manage Jay directly","imageSrcUrl":"/personal/images/colleagues/jay_patel.jpeg","text":"I had the pleasure of working with Richard at Commure and I highly recommend Richard as an exceptional software architect who combines technical mastery with remarkable execution speed. During our time working together, Richard consistently demonstrated an impressive understanding of complex technical challenges across the entire technology stack - from frontend to backend to infrastructure to databases, and cloud architecture.\\n\\nWhat sets Richard apart is his ability to rapidly assess requirements, design elegant solutions, and execute with precision. His deep expertise in AI technologies has been particularly valuable, as he seamlessly integrates RAG capabilities into broader system architectures while maintaining performance and scalability standards. Richard doesn\'t just understand individual technologies; he sees how they interconnect and leverages this holistic view to make informed architectural decisions.\\n\\nRichard\'s speed of execution is truly remarkable - he can move from concept to implementation at lightning speed. Yet this speed never comes at the expense of quality or thoroughness. His solutions are well-architected, documented, and built to last.\\n\\nAny organization would benefit greatly from Richard\'s technical leadership, strategic thinking, and ability to deliver results quickly while maintaining the highest standards of software architecture."},{"name":"Chance Yohman","title":"Lead Software Engineer at LogicManager","date":"September 1, 2025","relationship":"was Richard\'s teacher","imageSrcUrl":"/personal/images/colleagues/chance_yohman.jpeg","text":"I had the pleasure of teaching Richard Franks in my Intro to Java class at the University of Southern Maine in 2005. Even then, his curiosity and dedication stood out. Since then, he has built an impressive career, rising to Senior Software Architect and Principal Software Engineer. Richard combines deep technical expertise with strategic thinking, making him a standout professional in any software engineering team."},{"name":"Stacey Leadbeater","title":"Product Management | Healthcare","date":"March 6, 2020","relationship":"worked with Richard on the same team","imageSrcUrl":"/personal/images/colleagues/stacey_leadbeater.jpeg","text":"I have had the pleasure of working closely with Richard for many years as a product manager. Richard has been a lead, integral part of completely rewriting a legacy physician-facing portal into a customizable dashboard framework with modern technology - no small or easy feat.\\n\\nRichard always goes out of his way to truly understand workflows and the end user problems, as well as consider technical aspects in order to implement the right solution. He is a true team player: working with product and UX to design the right changes; consulting with other developers and providing documentation to ensure they are following best implementation practices and agreed-upon methods; working with QA to ensure changes are fully tested and automation has what they need; and reviewing end user documentation.\\n\\nRichard is a leader, and as an architect is often called on to advise on the right technical changes to make. He is diligent about documenting his work, which allows other engineers to more easily come on board. He is always willing to provide guidance and input to others in development.\\n\\nRichard is so good that he\'s in the sometimes unenviable position of being the go-to person to fix any problem. This means he solves many of the toughest problems, which are often critical in nature and requiring a solution ASAP, and which pull him away from other items he may be working on. He is an excellent multi-tasker and able to jump in to help in almost any situation.\\n\\nI enjoy working with Richard very much, and would choose to be on a team with him in a heartbeat!"},{"name":"Richard Tang","title":"Senior Software Engineer | Front-end Software Engineer","date":"March 5, 2020","relationship":"was senior to Richard but didn\'t manage him directly","imageSrcUrl":"/personal/images/colleagues/richard_tang.jpeg","text":"Richard is truly the most brilliant software engineer/developer/architect I have worked with. We have worked together since 2015 (~5 years at the time of this writing). I used to think the \\"10x developer\\" was a myth, but he is the closest to that I have seen! It\'s amazing how quickly he is able to build features/functionality while still achieving high quality and flexibility. Being able to work with him on the same team (\\"core\\" code/functionality) has allowed me to learn so much about design, architecture, and best practices. I have definitely become a much better UI/front-end and full-stack developer because of him... he is the go-to guy, so whether it\'s asking him questions (he\'s very helpful), or just looking at his code, there is a lot to learn from him."},{"name":"Satyajeet Nandekar","title":"Software Engineer at Amazon Web Services (AWS)","date":"February 24, 2020","relationship":"worked with Richard on the same team","imageSrcUrl":"/personal/images/colleagues/satyajeet_nandekar.jpeg","text":"It is a pleasure to work with Richard Franks in the same team for more than 5 years. During this time, we worked very closely on multiple successful projects from start to finish. He is creative, energetic, solution oriented, highly motivated with great communication skills and aims for excellence all the time.\\n\\nRichard’s deeper understanding of the technical nuances always helped us during the tough time of our project. His inputs in design discussions and architecture meetings have always been valuable. From my past experience, I can easily say that a problem assigned to him is already half solved. He is an asset to any company."},{"name":"Jane Florins","title":"UX/UI Leader | Elevating User Experiences & Driving Business Growth through Innovative Designs.","date":"February 20, 2020","relationship":"was senior to Richard but didn\'t manage him directly","imageSrcUrl":"/personal/images/colleagues/jane_florins.jpeg","text":"I worked with Richard on a number of projects and features at Patient Keeper. What makes him stand out is his deep care about his work and the overall success of the company. He is willing to take risks and responsibilities when he sees an opportunity to improve the project. Richard\'s approach to work is innovative. He is constantly coming up with new ideas, he does his research before attacking a problem. Richard is a meticulous perfectionist who doesn\'t give up unless his work is done to the highest quality. He is a good team player who is always ready to jump in and help his co-workers. He cares about UX/UI, and he cares about our customers and their experience. He made a significant effort to make our product look polished and work faster. I would highly recommend Richard for his personality and skills."},{"name":"Ritika Nanda","title":"Senior Software Engineer at Google","date":"August 8, 2016","relationship":"Richard was senior to Ritika but didn\'t manage her directly","imageSrcUrl":"/personal/images/colleagues/ritika_nanda.jpeg","text":"It was a pleasure working with Richard at Patient Keeper. He is one of the best developers and architecture designers I have ever worked with.\\n\\nHe was very helpful to co-workers. He always came up with creative and out of the box ideas for solving problems.\\n\\nRichard came up with robust design and code for all the projects I worked with him.\\n\\nHe is a great developer and a team worker. I got a chance to learn a lot from him."},{"name":"Amisha Thakkar Kashyap","title":"Head of AI Products - Product Management","date":"January 18, 2015","relationship":"worked with Richard but on different teams","imageSrcUrl":"/personal/images/colleagues/amisha_thakkar_kashyap.jpeg","text":"Richard is an uber-talented architect and development lead. He leads by example by setting high standards. He is a rare engineer who thinks both about smart software development and the user.\\n\\nHe designs intuitive software. He builds scalable, extensible products that are user-friendly. He leverages the latest in technology and design patterns. His code is elegant, built with reliable, extensible foundations and great frameworks.\\n\\nIn all aspects of software development Richard is superb - design, testing and documentation. He delivers high quality products on-time which have unit-tests and code documentation even under tough deadlines. He thinks not just about product design and features but also about the maintenance of the code in the future. He writes self testing code that prevents regression defects. In the time I worked with him I saw him introduce new frameworks, unit tests, self documenting capabilities in an older stringent code base.\\n\\nHe is an excellent mentor. He works incredibly hard and it is a pleasure to work with him. Richard is an invaluable asset to any team he leads!"},{"name":"Dave Tran","title":"Mission-Driven Engineering Leader | Unlocking Team Superpowers and Turning Challenges into Triumphs!","date":"November 3, 2013","relationship":"worked with Richard on the same team","imageSrcUrl":"/personal/images/colleagues/dave_tran.jpeg","text":"Rich was an amazing team member to work with and was instrumental in helping the team deliver the next generation patient list solution. Rich was not only laser focused on implementing the web portion of the solution but he was also equally focused on improving the UI architecture of the overall application. He incorporated industry best practices and reusable web components to facilitate better design decisions for multiple development teams moving forward. Rich understands how to meet and exceed client\'s expectations with innovative web solutions and if given another opportunity to work with Rich, I would jump at the chance to do so!"},{"name":"Melissa Snyder","title":"Software Design Architect at COCC","date":"January 20, 2012","relationship":"worked with Richard on the same team","imageSrcUrl":"/personal/images/colleagues/melissa_snyder.jpeg","text":"I had the opportunity to work with Richard for over a year as part of a full application rewrite. He is extremely conscientious and consistently offers up suggestions for how to make coding more efficient, to improve code quality and to improve the end-user experience. He was also able to help me and others without coding backgrounds to understand the possibilities and constraints of the system we were building. Richard is always willing to help a coworker by answering a question, troubleshooting an issue, or brainstorming product solutions. He is a great person to work with and always delivers a quality product."},{"name":"Paul Russell","title":"Software Engineer at WiseTech Global","date":"January 8, 2012","relationship":"worked with Richard on the same team","text":"Richard is a brilliant software developer. He has exceptional design skills and continuously searches for ways to improve the quality of the software.\\n\\nHe takes the time to answer questions from colleagues and is always available when there is a problem."},{"name":"Nathan Babb","title":"Software Consultant at IDEXX","date":"January 5, 2012","relationship":"worked with Richard on the same team","imageSrcUrl":"/personal/images/colleagues/nathan_babb.jpeg","text":"Richard is a personable colleague, a talented software engineer and it has been a pleasure working with him. He is committed to writing quality code, and it shows in his practical, concise designs. Richard has very high personal standards and integrity, and he often goes out of his way to help others and take on challenging tasks. I\'ve enjoyed collaborating with Richard, where his focus is towards producing the best design possible. He is diligent with coding standards, and is very productive as well. He gets my hearty recommendation!"},{"name":"Jim Levin","title":"Senior Product Analyst with a specific expertise in analysis, user experience and user interface design","date":"December 30, 2011","relationship":"worked with Richard on the same team","imageSrcUrl":"/personal/images/colleagues/jim_levin.jpeg","text":"Rich is a professional, thorough and thoughtful developer - that I would recommend/refer without hesitation."},{"name":"Phelps Peeler","title":"Proven Product and Technology Leadership","date":"October 22, 2010","relationship":"managed Richard directly","imageSrcUrl":"/personal/images/colleagues/phelps_peeler.jpeg","text":"Richard is an exceptionally talented engineer. Very early in his career he has demonstrated the ability to resolve the type of complex issues that can stymie gifted developers with significantly more experience. During the time Richard worked for me he consistently performed above the expectations that were set for him, even as those expectations were raised with each additional success.\\n\\nRichard is methodical when attacking a problem -- he consistently identifies and addresses edge-cases that are missed in the business requirements and he shows a greater dedication than any engineer I\'ve ever worked with to developing and implementing test cases that mirror production as closely as is possible. This significantly reduced risk, and rendered deployments that could have been nerve-wracking stress-free.\\n\\nRichard\'s work required constant interaction with critical external business partners. Richard excelled both at the immediate task at hand and at developing lasting relationships with these partners. First Data, a giant organization that has run literally thousands of companies through a particular, complicated certification process, reported that Richard completed the necessary tasks more quickly than anyone before him. Multiple partners reached out to tell me how much they enjoyed working with Richard, and the relationships Richard developed enabled us to convince these partners to accelerate their standard timeline in ways that allowed us to accomplish things we couldn\'t have otherwise.\\n\\nRichard is bursting with talent, and I\'m very excited to see where his career will take him, and I\'m confident that he\'ll excel wherever he ends up."},{"name":"Bill Hardwick","title":"Software Engineering Leader","date":"July 14, 2010","relationship":"worked with Richard on the same team","imageSrcUrl":"/personal/images/colleagues/bill_hardwick.jpeg","text":"Richard is a very skilled developer with a passion for technology. He is a creative problem-solver and is always looking to utilize the latest tools, frameworks, and design patterns to keep him on the cutting edge of the industry. His work ethic is outstanding and he gets the job done fast and efficiently, without sacrificing the quality of his code. I would recommend Richard to anyone looking for a talented developer who works well with others or independently."},{"name":"Mat Young","title":"Art Director at Transparent Audio","date":"July 7, 2009","relationship":"worked with Richard on the same team","imageSrcUrl":"/personal/images/colleagues/mat_young.jpeg","text":"Richard is a creative problem solver who will always look for the best solution.\\n\\nHe is willing to go the extra mile and endeavor in new areas for the sake of the best possible product.\\n\\nHe is very easy to work with and you can count on him to follow through.\\n\\nI highly recommend Richard."},{"name":"Joe Myers","title":"Head of Product Design & User Experience @ Gannett | USA TODAY NETWORK — Driving clean, enjoyable, and accessible solutions at scale","date":"October 2, 2008","relationship":"worked with Richard on the same team","imageSrcUrl":"/personal/images/colleagues/joe_myers.jpeg","text":"Please do not talk to Richard about other jobs. He is an indispensable member of OUR development team. We found him first and he\'s not allowed to leave. Richard breezes through complicated work with a can-do attitude while adding invaluable insight. He brings his \\"A-Game\\" every day, and if there\'s any doubt in his mind, he\'ll step back, slam a Monster™ Energy Drink® before high-stepping into the end-zone. Too bad he\'s not allowed to talk to you."}]},"education":[{"school":"Boston University","degree":"B.S. Biomedical Engineering","year":"2003","image":"/personal/images/education/bu.jpeg","awards":["Order of the Engineer • Engineering • 1998"]},{"school":"University of Southern Maine","degree":"M.S. Computer Science","year":"2008","image":"/personal/images/education/usm.jpeg","awards":["Graduate Student of the Year • Computer Science • 2008"]}],"projectsSection":{"title":"Projects","descriptionLines":["Selected work across AI-assisted systems, full-stack product engineering, and experimental applications.","Contact me if you\'d like a demo of AI functionality or a temporary OpenAI API key to try AI functionality out."],"launchLabel":"Launch","interestHeading":"Why this interests me...","accoladesHeading":"Accolades","marks":[{"kind":"image","src":"/dna/images/geneboard_banner.png","alt":"GeneBoard banner","className":"-left-6 top-2 w-36 rotate-[-10deg] lg:-left-4 lg:top-4 lg:w-40","imageClassName":"h-auto w-full object-contain","width":260,"height":78},{"kind":"image","src":"/logo192.png","alt":"Bookworm logo","className":"left-52 top-0 h-16 w-16 rotate-[8deg] lg:left-64 lg:h-20 lg:w-20","imageClassName":"h-full w-full rounded-2xl object-contain","width":192,"height":194},{"kind":"image","src":"/assets/titles/warbirds_title.png","alt":"Warbirds title","className":"right-0 top-12 w-40 rotate-[-5deg] lg:w-48","imageClassName":"h-auto w-full object-contain","width":220,"height":80},{"kind":"cardsFan","className":"absolute right-28 top-2 h-28 w-28 rotate-[10deg] opacity-35 transition-transform duration-500","cards":[{"src":"/assets/cards/PNG/Cards (medium)/card_back.png","alt":"Playing card back","width":110,"height":154,"className":"absolute left-0 top-3 h-24 w-auto rounded-lg object-contain drop-shadow-xl"},{"src":"/assets/cards/PNG/Cards (medium)/card_spades_J.png","alt":"Jack of spades","width":110,"height":154,"className":"absolute left-6 top-1 h-24 w-auto rounded-lg object-contain drop-shadow-xl"},{"src":"/assets/cards/PNG/Cards (medium)/card_spades_A.png","alt":"Ace of spades","width":110,"height":154,"className":"absolute left-12 top-0 h-24 w-auto rounded-lg object-contain drop-shadow-xl"}]}]}}'))}]);